            if (maxDoc && maxDoc.id) {
              const maxId = maxDoc.id instanceof Long ? maxDoc.id : Long.fromNumber(Number(maxDoc.id));
              nextId = Long.fromNumber(maxId.toNumber() + 1);
            }
            
            // Extract user_id from authenticated user (set by authMiddleware)
